def linear_search(items, target):
    for i in range(len(items)):
        if items[i] == target:
            return i
    return -1


numbers = [17, 4, 23, 8, 42, 15, 9]

print(linear_search(numbers, 42))
print(linear_search(numbers, 99))

def binary_search(items, target):
    low = 0
    high = len(items) - 1

    while low <= high:
        middle = (low + high) // 2

        if items[middle] == target:
            return middle
        elif items[middle] < target:
            low = middle + 1
        else:
            high = middle - 1

    return -1


numbers = [4, 8, 9, 15, 17, 23, 42]

print(binary_search(numbers, 42))
print(binary_search(numbers, 4))
print(binary_search(numbers, 99))

def selection_sort(items):
    result = items.copy()

    for i in range(len(result)):
        smallest = i
        for j in range(i + 1, len(result)):
            if result[j] < result[smallest]:
                smallest = j
        result[i], result[smallest] = result[smallest], result[i]

    return result


print(selection_sort([64, 25, 12, 22, 11]))

def linear_search_counted(items, target):
    comparisons = 0
    for i in range(len(items)):
        comparisons += 1
        if items[i] == target:
            return i, comparisons
    return -1, comparisons


index, comparisons = linear_search_counted([5, 3, 8, 1, 9], 1)
print(index, comparisons)

def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)


print(factorial(5))

def reverse(text):
    if len(text) <= 1:
        return text
    return reverse(text[1:]) + text[0]


